window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[319]={"id":"319","numero":319,"titre":"Lymphomes malins","objectifs":[{"id":"319-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques qui peuvent faire suspecter un lymphome","contenu":"<p>Un lymphome se révèle par un <strong><span class=\"kw-def\">syndrome tumoral</span></strong> (atteinte des organes lymphoïdes) et/ou des <strong><span class=\"kw-clinique\">signes généraux</span></strong>. Comme les cellules lymphoïdes sont présentes dans tout l'organisme, <em>toute aire ganglionnaire et tout viscère</em> peut être touché.</p>\n      <table >\n        <thead><tr><th>Présentation</th><th>Caractéristiques évocatrices</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes B</strong><br>(signes généraux)</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Fièvre</span> :</strong> <span class=\"kw-clinique\">fièvre / fébricule</span> au long cours <span class=\"kw-chiffre\">≥ 38 °C</span> pendant <span class=\"kw-chiffre\">≥ 8 jours</span>, sans infection retrouvée<br>\n              <strong><span class=\"kw-clinique\">Sueurs</span> :</strong> <span class=\"kw-clinique\">sueurs profuses</span>, notamment <strong>nocturnes</strong><br>\n              <strong><span class=\"kw-clinique\">Amaigrissement</span> :</strong> <span class=\"kw-chiffre\">&gt; 10 %</span> du poids en <span class=\"kw-chiffre\">&lt; 6 mois</span><br>\n              <strong><span class=\"kw-clinique\">AEG</span> :</strong> <span class=\"kw-clinique\">altération de l'état général</span> (<span class=\"kw-bio\">Performance Status</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Adénopathie</span> superficielle suspecte</strong></td>\n            <td>\n              <strong>Taille :</strong> <span class=\"kw-chiffre\">&gt; 2 cm</span><br>\n              <strong>Ancienneté :</strong> <span class=\"kw-chiffre\">&gt; 1 mois</span><br>\n              <strong>Consistance :</strong> <span class=\"kw-clinique\">ferme</span>, non <span class=\"kw-etio\">inflammatoire</span><br>\n              <strong>Mobilité :</strong> <span class=\"kw-clinique\">mobile</span>, non adhérente aux plans superficiels et profonds<br>\n              <strong>Douleur :</strong> <span class=\"kw-clinique\">indolore</span><br>\n              <strong>Signes négatifs :</strong> pas de porte d'entrée infectieuse ; pas de <span class=\"kw-clinique\">lésion</span> <span class=\"kw-etio\">tumorale</span> locorégionale (≠ <span class=\"kw-clinique\">adénopathie</span> satellite de cancer ou d'infection)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anneau de Waldeyer</strong></td>\n            <td>Hypertrophie <span class=\"kw-clinique\">amygdalienne</span>, de la base de langue ou du cavum : asymptomatique, ou dysphagie, odynophagie, dysphonie, <span class=\"kw-clinique\">otalgie</span> réflexe</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Adénopathies</span> profondes</strong></td>\n            <td>\n              <strong>Médiastin :</strong> <span class=\"kw-clinique\">dyspnée</span> ; <span class=\"kw-clinique\">toux</span> ; <span class=\"kw-alerte\">syndrome cave supérieur</span><br>\n              <strong>Abdomen :</strong> <span class=\"kw-clinique\">syndrome occlusif</span> (lymphome de Burkitt iléo-cæcal) ; <span class=\"kw-clinique\">ascite</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hépato-<span class=\"kw-clinique\">splénomégalie</span></strong></td>\n            <td><span class=\"kw-clinique\">Splénomégalie</span> et/ou <span class=\"kw-clinique\">hépatomégalie</span> ± importantes</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span></strong></td>\n            <td><span class=\"kw-clinique\">Prurit</span> parfois isolé, sans <span class=\"kw-clinique\">adénopathie</span> superficielle (oriente vers un lymphome de Hodgkin)</td>\n          </tr>\n          <tr>\n            <td><strong>Atteintes extra-ganglionnaires</strong></td>\n            <td>\n              <strong>Tube digestif :</strong> troubles dyspeptiques ; <span class=\"kw-clinique\">diarrhée</span> ; hémorragie digestive<br>\n              <strong>ORL :</strong> sinus ; glandes salivaires ; thyroïde<br>\n              <strong>Cutané :</strong> nodules ; plaques ; érythrodermie<br>\n              <strong>Œil :</strong> lésions conjonctivales ; exophtalmie<br>\n              <strong>SNC :</strong> <span class=\"kw-clinique\">confusion</span> ; crise comitiale ; <span class=\"kw-clinique\">déficit moteur</span><br>\n              <strong>Testicule :</strong> <span class=\"kw-clinique\">masse</span> scrotale (sujet âgé)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> L'<span class=\"kw-clinique\">adénopathie</span> lymphomateuse est <strong><span class=\"kw-clinique\">indolore</span></strong> — sauf la rare mais très spécifique <strong><span class=\"kw-alerte\">douleur ganglionnaire déclenchée par l'ingestion d'alcool</span></strong>, évocatrice du <span class=\"kw-def\">lymphome de Hodgkin</span>. Un <span class=\"kw-clinique\">prurit</span> chronique apparemment isolé doit aussi faire évoquer un Hodgkin.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 220 — ADP superficielle · 275 — <span class=\"kw-clinique\">Splénomégalie</span> · 217 — Syndrome mononucléosique</em></p>","frequence":4},{"id":"319-2","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les situations d’urgence dans les lymphomes","contenu":"<p>Les urgences des lymphomes sont de deux ordres : <strong>compressives</strong> (le syndrome <span class=\"kw-etio\">tumoral</span> comprime une structure vitale) et <strong>métaboliques</strong> (lyse cellulaire massive, activation macrophagique). Elles concernent surtout les <span class=\"kw-def\">lymphomes agressifs</span>.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> — 3 tableaux compressifs.</strong>\n        <ul>\n          <li><strong><span class=\"kw-alerte\">Syndrome cave supérieur</span></strong> : compression de la veine cave par une <span class=\"kw-clinique\">masse</span> médiastinale volumineuse.</li>\n          <li><strong><span class=\"kw-alerte\">Compression radiculo-médullaire</span></strong> : <span class=\"kw-clinique\">syndrome de compression</span> médullaire ou syndrome de la queue de cheval secondaire au lymphome.</li>\n          <li><strong><span class=\"kw-alerte\">Masse abdominale d'évolution rapide</span></strong> : douleurs, syndrome occlusif — peut révéler un <span class=\"kw-def\">lymphome de Burkitt</span> (enfant / adulte jeune) et impose la recherche d'un <span class=\"kw-clinique\">syndrome de lyse</span> <span class=\"kw-etio\">tumorale</span> spontané.</li>\n        </ul>\n      </div>\n      <p><strong>Syndrome cave supérieur</strong> — moyen mnémo <strong>TOCTOC</strong> : <span class=\"kw-clinique\">œdème en pèlerine</span>, <span class=\"kw-clinique\">turgescence jugulaire</span>, <span class=\"kw-clinique\">circulation veineuse collatérale thoracique</span>, <span class=\"kw-clinique\">orthopnée</span> / <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">céphalées</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span> métabolique</th><th>Reconnaître</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Syndrome de lyse</span> <span class=\"kw-etio\">tumorale</span></strong><br>(relargage massif de composés intracellulaires)</td>\n            <td>\n              <strong>Définition <span class=\"kw-ttt\">biologique</span> :</strong> <span class=\"kw-chiffre\">≥ 2/4</span> anomalies — <span class=\"kw-bio\">hyperuricémie</span> ; <span class=\"kw-bio\">hyperkaliémie</span> ; <span class=\"kw-bio\">hyperphosphorémie</span> ; <span class=\"kw-bio\">hypocalcémie</span><br>\n              <strong>Marqueur :</strong> élévation des <span class=\"kw-bio\">LDH</span> proportionnelle à la lyse<br>\n              <strong>Conséquences :</strong> <span class=\"kw-alerte\">insuffisance rénale aiguë</span> (quasi constante) ; troubles du rythme ; <span class=\"kw-clinique\">convulsions</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Syndrome d'activation macrophagique (SAM)</strong><br>(rare, mortel sans traitement)</td>\n            <td>\n              <strong>Clinique :</strong> tableau bruyant — <span class=\"kw-clinique\">fièvre élevée</span> ; <span class=\"kw-clinique\">hépato-splénomégalie</span> ; <span class=\"kw-clinique\">syndrome confusionnel</span><br>\n              <strong>Biologie :</strong> <span class=\"kw-bio\">cytopénies</span> ; <span class=\"kw-bio\">hyperferritinémie</span> ; <span class=\"kw-bio\">hypertriglycéridémie</span> ; <span class=\"kw-bio\">hypofibrinogénémie</span> ; <span class=\"kw-bio\">hyponatrémie</span><br>\n              <strong>Confirmation :</strong> images d'<span class=\"kw-bio\">hémophagocytose</span> au myélogramme (non indispensable pour traiter)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Prévention du <span class=\"kw-clinique\">syndrome de lyse</span></strong> : <span class=\"kw-ttt\">hyperhydratation</span> par sérum physiologique (maintien d'une diurèse satisfaisante), associée à un hypouricémiant adapté au risque — <span class=\"kw-ttt\">rasburicase</span> si hyperleucocytose ou forte <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span>, <span class=\"kw-ttt\">allopurinol</span> dans les autres cas.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Ne <span class=\"kw-ci\">pas alcaliniser les urines</span> au cours d'un <span class=\"kw-clinique\">syndrome de lyse</span> : l'alcalinisation augmente le <span class=\"kw-alerte\">risque de précipitation de cristaux de phosphate de calcium</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 93 — Compression médullaire non trauma</em></p>","frequence":5},{"id":"319-3","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Décrire les caractéristiques générales et les principes de la classification des lymphomes","contenu":"<p>Les <strong><span class=\"kw-def\">lymphomes malins</span></strong> sont des hémopathies lymphoïdes malignes : des <strong>proliférations clonales <span class=\"kw-def\">extra-médullaires</span></strong> de <span class=\"kw-bio\">lymphocytes</span> <strong>matures</strong> (<span class=\"kw-def\">B</span>, <span class=\"kw-def\">T</span> ou <span class=\"kw-def\">NK</span>). Exception : les <span class=\"kw-def\">lymphomes lymphoblastiques</span>, qui correspondent à une prolifération de cellules <strong>immatures</strong>. Ils représentent environ <span class=\"kw-chiffre\">40 %</span> des hémopathies malignes.</p>\n      <p>On distingue <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>rands types</strong> selon la présence ou non de la <strong><span class=\"kw-def\">cellule de Reed-Sternberg</span></strong> : le <strong>lymphome de Hodgkin (LH)</strong> et les <strong>lymphomes non hodgkiniens (LNH)</strong>.</p>\n      <table >\n        <thead><tr><th></th><th>Lymphome de Hodgkin</th><th>Lymphome non hodgkinien</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span></strong></td>\n            <td><span class=\"kw-chiffre\">2 000</span> nouveaux cas/an, stable</td>\n            <td><span class=\"kw-chiffre\">17 000</span> nouveaux cas/an, en augmentation (× 7 <span class=\"kw-bio\">vs</span> LH)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>2 pics : <span class=\"kw-chiffre\">15-35 ans</span> (cancer le plus fréquent avant <span class=\"kw-chiffre\">40 ans</span>) et <span class=\"kw-chiffre\">~ 70 ans</span></td>\n            <td>Sujet plus âgé, âge médian <span class=\"kw-chiffre\">65 ans</span> ; Burkitt surtout chez l'enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Extension</strong></td>\n            <td>Le plus souvent localisé, sus-diaphragmatique</td>\n            <td>Souvent disséminé</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Classification</span> OMS</strong></td>\n            <td>Cellule de <span class=\"kw-def\">Reed-Sternberg</span> (<span class=\"kw-bio\">CD15+</span>, <span class=\"kw-bio\">CD30+</span>, <span class=\"kw-bio\">CD20−</span>, <span class=\"kw-bio\">CD45−</span>) ; LH classique <span class=\"kw-chiffre\">95 %</span> <span class=\"kw-bio\">vs</span> LH à prédominance lymphocytaire nodulaire <span class=\"kw-chiffre\">5 %</span></td>\n            <td>Phénotype <span class=\"kw-bio\">B</span> (<span class=\"kw-chiffre\">85 %</span>, <span class=\"kw-bio\">CD20+</span>) ou <span class=\"kw-bio\">T / NK</span> (<span class=\"kw-chiffre\">15 %</span>, <span class=\"kw-bio\">CD3+</span>) ; nombreux types histologiques</td>\n          </tr>\n          <tr>\n            <td><strong>Guérison</strong></td>\n            <td><span class=\"kw-chiffre\">~ 90 %</span> (tous stades confondus)</td>\n            <td><span class=\"kw-chiffre\">~ 50 %</span> (tous types confondus)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Les <strong>LNH</strong> se classent aussi selon leur <strong>comportement clinique</strong>, qui conditionne le <span class=\"kw-def\">pronostic</span> et le traitement :</p>\n      <table >\n        <thead><tr><th>LNH indolents (bas <span class=\"kw-def\">grade</span>)</th><th>LNH agressifs (haut grade)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Type :</strong> <span class=\"kw-def\">lymphome folliculaire</span> (<span class=\"kw-def\">pronostic</span> FLIPI) ; zone marginale / MALT ; lymphocytique<br>\n              <strong><span class=\"kw-bio\">Histologie</span> :</strong> architecture <span class=\"kw-bio\">nodulaire</span> conservée ; petites cellules<br>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> lente (mois / années) ; paucisymptomatique ; guérison exceptionnelle mais survie prolongée\n            </td>\n            <td>\n              <strong>Type :</strong> <span class=\"kw-def\">lymphome B diffus à grandes cellules</span> (<span class=\"kw-def\">pronostic</span> IPI) ; <span class=\"kw-def\">Burkitt</span><br>\n              <strong><span class=\"kw-bio\">Histologie</span> :</strong> architecture <span class=\"kw-alerte\">détruite</span> ; grandes cellules<br>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> rapide (semaines) ; symptomatique ; péjorative sans traitement mais guérison possible\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/319/schema-origine-lnh-b.png\" alt=\"Schéma du follicule ganglionnaire localisant l'origine des principaux lymphomes B selon la zone : centre germinatif, zone du manteau, zone marginale\" loading=\"lazy\">\n        <figcaption>Origine des principaux LNH B selon la zone du follicule ganglionnaire : lymphome à grandes cellules B et lymphome de Burkitt (centre germinatif), lymphome folliculaire (centre germinatif), lymphome du manteau (zone du manteau), lymphomes de la zone marginale et du MALT (zone marginale). Source : fiche source EDN item 319 — Lymphomes malins.</figcaption>\n      </figure>\n      <p>Les <span class=\"kw-def\">LNH-T</span> extra-ganglionnaires regroupent notamment les lymphomes cutanés T épidermotropes — <span class=\"kw-def\">mycosis fongoïde</span> (le lymphome cutané le plus fréquent) et <span class=\"kw-def\">syndrome de Sézary</span> (forme érythrodermique et leucémique du mycosis fongoïde).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 318 — Leucémie lymphoïde chronique</em></p>","frequence":3},{"id":"319-4","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les principaux facteurs étiologiques des lymphomes non hodgkiniens","contenu":"<p>Dans la grande majorité des cas, les <span class=\"kw-def\">LNH</span> sont <strong><span class=\"kw-etio\">sporadiques</span></strong> : <span class=\"kw-chiffre\">90-95 %</span> surviennent sans agent étiologique identifié. Les <span class=\"kw-def\">facteurs de risque</span> connus se répartissent en grandes catégories.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Agents et associations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Virus</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">VIH</span> :</strong> LNH agressif — <span class=\"kw-alerte\">classant SIDA</span><br>\n              <strong><span class=\"kw-etio\">EBV</span> :</strong> lymphome de Burkitt endémique (Afrique) ; lymphome de l'immunodéprimé<br>\n              <strong><span class=\"kw-etio\">HTLV-1</span> :</strong> leucémie / lymphome T de l'adulte<br>\n              <strong><span class=\"kw-etio\">VHC</span> :</strong> lymphome de la zone marginale splénique<br>\n              <strong><span class=\"kw-etio\">HHV-8</span> :</strong> lymphome des séreuses (patient <span class=\"kw-etio\">VIH</span>+)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bactéries</strong><br>(lymphomes du MALT)</td>\n            <td>\n              <strong><span class=\"kw-etio\">Helicobacter pylori</span> :</strong> MALT gastrique<br>\n              <strong><span class=\"kw-etio\">Borrelia burgdorferi</span> :</strong> MALT cutané<br>\n              <strong><span class=\"kw-etio\">Campylobacter jejuni</span> :</strong> MALT de l'intestin grêle<br>\n              <strong><span class=\"kw-etio\">Chlamydia psittaci</span> :</strong> MALT oculaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Immunosuppression</strong></td>\n            <td>\n              <strong>Constitutionnelle :</strong> <span class=\"kw-etio\">syndrome de Wiskott-Aldrich</span> ; <span class=\"kw-etio\">ataxie-télangiectasie</span><br>\n              <strong><span class=\"kw-etio\">Acquise</span> :</strong> <span class=\"kw-etio\">VIH</span> ; <span class=\"kw-ttt\">immunosuppresseurs</span> ; transplantation\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maladies auto-immunes</strong></td>\n            <td><span class=\"kw-etio\">Syndrome de Sjögren</span> ; <span class=\"kw-etio\">polyarthrite rhumatoïde</span> ; <span class=\"kw-etio\">lupus</span> ; <span class=\"kw-etio\">maladie cœliaque</span></td>\n          </tr>\n          <tr>\n            <td><strong>Expositions professionnelles</strong></td>\n            <td><span class=\"kw-etio\">Pesticides</span> (agriculteurs, viticulteurs) ; <span class=\"kw-etio\">solvants</span> et dioxine — possible reconnaissance en maladie professionnelle</td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td><span class=\"kw-etio\">Antécédents familiaux</span> d'hémopathie ; polymorphismes constitutionnels de susceptibilité (pas de <span class=\"kw-def\">dépistage</span> <span class=\"kw-etio\">génétique</span> en pratique)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique EDN.</strong> Le <strong><span class=\"kw-def\">LNH</span> est classant SIDA</strong> ; le <strong><span class=\"kw-def\">lymphome de Hodgkin</span> ne l'est PAS</strong> — bien que l'infection à <span class=\"kw-etio\">VIH</span> soit un <span class=\"kw-def\">facteur de risque</span> des deux.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 272 — Ulcère gastroduodénal - gastrite</em></p>","frequence":4},{"id":"319-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration en imagerie initiale du lymphome","contenu":"<p>L'imagerie a deux objectifs au diagnostic d'un lymphome : <strong>réaliser le <span class=\"kw-def\">bilan d'extension</span></strong> (déterminer le <span class=\"kw-def\">stade</span>) et <strong>évaluer la <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span></strong>. Trois modalités structurent ce bilan.</p>\n      <table >\n        <thead><tr><th>Modalité</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Radiographie thoracique</span></strong></td>\n            <td>Sert de référence ; évalue le syndrome <span class=\"kw-etio\">tumoral</span> médiastinal — <span class=\"kw-alerte\">rapport médiastino-thoracique &gt; 0,35</span> dans les formes <em>bulky</em></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Scanner thoraco-abdomino-pelvien</span></strong></td>\n            <td>Recherche les localisations ganglionnaires et extra-ganglionnaires <strong>profondes</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TEP-TDM</span></strong> (au <span class=\"kw-bio\">18-FDG</span>)</td>\n            <td>\n              Examen <strong>central</strong> du bilan initial et de l'évaluation thérapeutique, pour les lymphomes <strong>avides de FDG</strong> :<br>\n              <strong>Concernés :</strong> lymphome de Hodgkin ; lymphome folliculaire ; lymphome du manteau ; lymphomes agressifs (B diffus à grandes cellules, Burkitt)<br>\n              <strong>Conséquence :</strong> dispense le plus souvent de la <span class=\"kw-bio\">biopsie ostéo-médullaire</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/319/tep-tdm-corps-entier.png\" alt=\"TEP-TDM au 18-FDG corps entier montrant de multiples foyers ganglionnaires hypermétaboliques au-dessus et au-dessous du diaphragme\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TEP</span>-<span class=\"kw-imagerie\">TDM</span> au 18-FDG, acquisition corps entier : multiples foyers ganglionnaires hypermétaboliques sus- et sous-diaphragmatiques — aspect de maladie disséminée. Source : fiche source EDN item 319 — Lymphomes malins.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/319/scanner-tap-adenopathies.png\" alt=\"Scanner thoraco-abdomino-pelvien en coupe coronale montrant de volumineuses adénopathies profondes abdominales\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Scanner</span> thoraco-abdomino-pelvien : volumineuses <span class=\"kw-clinique\">adénopathies</span> profondes abdominales, non accessibles à l'examen clinique. Source : fiche source EDN item 319 — Lymphomes malins.</figcaption>\n      </figure>\n      <p>Le bilan d'imagerie aboutit à la <strong><span class=\"kw-def\">classification d'Ann Arbor</span></strong>, qui définit le <span class=\"kw-def\">stade</span> du lymphome :</p>\n      <table >\n        <thead><tr><th>Stade</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>I</strong></td><td>Une seule aire ganglionnaire (ou un site extra-ganglionnaire localisé)</td></tr>\n          <tr><td><strong>II</strong></td><td><span class=\"kw-chiffre\">≥ 2</span> aires ganglionnaires d'un <strong>même côté</strong> du diaphragme</td></tr>\n          <tr><td><strong>III</strong></td><td>Aires ganglionnaires des <strong>2 côtés</strong> du diaphragme</td></tr>\n          <tr><td><strong>IV</strong></td><td>Atteinte viscérale (os, foie, poumon…) ou atteinte médullaire</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Suffixes :</strong> <strong>A</strong> = absence de signes généraux ; <strong>B</strong> = présence de signes généraux ; <strong>E</strong> = atteinte d'un viscère contigu par contiguïté ; <strong>X</strong> = <span class=\"kw-clinique\">masse</span> <em>bulky</em> (<span class=\"kw-chiffre\">&gt; 10 cm</span> ou rapport médiastino-thoracique <span class=\"kw-chiffre\">&gt; 0,35</span>).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/319/ann-arbor-stades.png\" alt=\"Schéma corporel des 4 stades de la classification d'Ann Arbor du lymphome\" loading=\"lazy\">\n        <figcaption><span class=\"kw-def\">Classification</span> d'Ann Arbor — stades I à IV selon le nombre d'aires ganglionnaires atteintes, leur position par rapport au diaphragme et l'existence d'une atteinte viscérale. Source : fiche source EDN item 319 — Lymphomes malins.</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Dans la <span class=\"kw-def\">classification</span> d'Ann Arbor, la <strong>rate compte comme un ganglion</strong>, et l'atteinte <strong>bilatérale axillaire = 2 aires</strong> (≠ classification de Binet de la LLC, où elle compte pour 1 seule aire).\n      </div>\n      <p>Les <span class=\"kw-bio\">LDH</span> sont un bon reflet de la <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span> : <span class=\"kw-chiffre\">subnormales</span> dans le LH et le lymphome folliculaire, <span class=\"kw-chiffre\">élevées</span> dans le lymphome B diffus à grandes cellules, <span class=\"kw-chiffre\">très élevées</span> dans le lymphome de Burkitt.</p>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/hodgkin-lymphoma","label":"Radiopaedia : Hodgkin lymphoma"},{"href":"https://radiopaedia.org/articles/lymphoma|","label":"Radiopaedia : Lymphoma|"},{"href":"https://radiopaedia.org/articles/lymphoma","label":"Radiopaedia : Lymphoma"},{"href":"https://radiopaedia.org/articles/non-hodgkin-lymphoma","label":"Radiopaedia : Non hodgkin lymphoma"}]},{"id":"319-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic histopathologique des lymphomes","contenu":"<p>Le diagnostic de lymphome est <strong>obligatoirement <span class=\"kw-def\">histologique</span></strong> : il nécessite l'analyse de <strong>tissu obtenu par <span class=\"kw-bio\">biopsie</span></strong>. En France, le réseau d'anatomopathologistes experts <strong><span class=\"kw-def\">Lymphopath</span></strong> assure la relecture systématique de tous les diagnostics de lymphome.</p>\n      <table >\n        <thead><tr><th>Prélèvement</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Recommandé</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">Biopsie</span> ganglionnaire chirurgicale</strong> (++) — <span class=\"kw-ttt\">exérèse</span> du ganglion entier<br>\n              <strong>Microbiopsie radioguidée percutanée</strong> — possible pour les localisations profondes\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non recommandé</strong></td>\n            <td>\n              <strong><span class=\"kw-ci\">Cytoponction ganglionnaire</span> :</strong> valeur d'orientation seule, <span class=\"kw-alerte\">ne suffit pas au diagnostic</span><br>\n              <strong><span class=\"kw-ci\">Curages ganglionnaires extensifs</span> :</strong> aucune vertu diagnostique ni pronostique ; retardent la <span class=\"kw-ttt\">chimiothérapie</span> ; risque <span class=\"kw-etio\">infectieux</span> local\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Site à biopsier</strong></td>\n            <td>Site <strong>ganglionnaire</strong> préféré à une localisation extra-ganglionnaire ; choisir le ganglion le plus pathologique (clinique, imagerie, <span class=\"kw-imagerie\">TEP</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Acheminement</strong></td>\n            <td>\n              Transport rapide au laboratoire, à l'<strong>état frais</strong> :<br>\n              <strong>Apposition sur lame :</strong> analyse cytologique<br>\n              <strong>Fixation formol + paraffine :</strong> analyse histologique<br>\n              <strong>Congélation d'un fragment :</strong> analyse moléculaire<br>\n              <strong>Mise en culture :</strong> analyse cytogénétique\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Cinq analyses complémentaires sont conduites sur le prélèvement :</p>\n      <table >\n        <thead><tr><th>Analyse</th><th>Apport diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Morphologique</strong></td>\n            <td>Architecture de la prolifération : <span class=\"kw-bio\">nodulaire</span> (architecture ganglionnaire respectée) ou <span class=\"kw-bio\">diffuse</span> (effacement) ; morphologie des cellules (taille, <span class=\"kw-bio\">mitoses</span>, chromatine)</td>\n          </tr>\n          <tr>\n            <td><strong>Cytologique</strong></td>\n            <td>Analyse fine des cellules, en complément de l'analyse histologique</td>\n          </tr>\n          <tr>\n            <td><strong>Immunophénotypique</strong></td>\n            <td>\n              Par <span class=\"kw-bio\">immunohistochimie</span> ou cytométrie en flux :<br>\n              <strong>Lignée :</strong> <span class=\"kw-bio\">CD45</span> (hématopoïétique) ; <span class=\"kw-bio\">CD20</span> (LB) ; <span class=\"kw-bio\">CD3</span> (LT)<br>\n              <strong>Lymphomes B à petites cellules :</strong> <span class=\"kw-bio\">CD5</span> ; <span class=\"kw-bio\">CD10</span> ; <span class=\"kw-bio\">CD23</span><br>\n              <strong>Lymphome de Hodgkin :</strong> <span class=\"kw-bio\">CD15</span> ; <span class=\"kw-bio\">CD30</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cytogénétique</strong></td>\n            <td>Recherche d'<span class=\"kw-etio\">EBV</span> par hybridation in situ (sonde <span class=\"kw-bio\">EBER</span>) ; anomalies chromosomiques récurrentes par caryotype ou <span class=\"kw-bio\">FISH</span></td>\n          </tr>\n          <tr>\n            <td><strong>Moléculaire</strong></td>\n            <td>Séquençage à haut débit (<span class=\"kw-bio\">NGS</span>) ; mise en évidence d'un <strong>réarrangement clonal</strong> des gènes des immunoglobulines (lymphomes B) ou du récepteur T (TCR, lymphomes T) — argument fort de malignité</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> La présence de <span class=\"kw-def\">cellules de Reed-Sternberg</span> sur une <span class=\"kw-ci\">cytoponction</span> <strong>ne suffit pas</strong> à affirmer un lymphome de Hodgkin : la <strong><span class=\"kw-bio\">biopsie</span> ganglionnaire reste indispensable</strong> — c'est l'architecture tissulaire qui fait le diagnostic.\n      </div>","frequence":7}],"astuces":[],"strategie":{"urgence":"<p><strong>Syndrome cave supérieur <span class=\"q\">— compression médiastinale</span></strong></p><p><span class=\"kw-imagerie\">imagerie thoracique</span> sans délai ; confirmer le lymphome (<span class=\"kw-bio\">biopsie</span>) puis <span class=\"kw-ttt\">chimiothérapie</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li>Compression de la <span class=\"kw-clinique\">veine cave supérieure</span> par une <span class=\"kw-clinique\">masse médiastinale</span> volumineuse</li><li>TOCTOC : <span class=\"kw-alerte\">œdème en pèlerine</span> · <span class=\"kw-clinique\">turgescence jugulaire</span> · <span class=\"kw-clinique\">circulation veineuse collatérale thoracique</span> · <span class=\"kw-clinique\">orthopnée</span> / <span class=\"kw-clinique\">toux</span> · <span class=\"kw-clinique\">céphalées</span></li></ul><p><strong>Compression radiculo-médullaire</strong></p><p><span class=\"kw-alerte\">urgence</span> diagnostique et thérapeutique — cf. <strong>item 93</strong> (compression médullaire non traumatique)</p><ul><li><span class=\"kw-alerte\">Syndrome de compression médullaire</span> ou <span class=\"kw-alerte\">syndrome de la queue de cheval</span> secondaire au lymphome</li></ul><p><strong><span class=\"kw-clinique\">Masse</span> abdominale d'<span class=\"kw-clinique\">évolution</span> rapide <span class=\"q\">— lymphome de Burkitt</span></strong></p><p>rechercher un <span class=\"kw-alerte\">syndrome de lyse tumorale spontané</span> ; <span class=\"kw-bio\">biopsie</span> la moins invasive (pas d'<span class=\"kw-ttt\">exérèse</span> complète)</p><ul><li><span class=\"kw-clinique\">Douleurs abdominales</span>, <span class=\"kw-clinique\">syndrome occlusif</span> (localisation iléo-cæcale)</li><li>Évoque un <span class=\"kw-def\">lymphome de Burkitt</span> (enfant / adulte jeune)</li></ul><p><strong><span class=\"kw-clinique\">Syndrome de lyse</span> <span class=\"kw-etio\">tumorale</span> <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> métabolique</span></strong></p><p>prévention : <span class=\"kw-ttt\">hyperhydratation</span> (sérum physiologique) + <span class=\"kw-ttt\">rasburicase</span> (hyperleucocytose / forte <span class=\"kw-clinique\">masse</span>) ou <span class=\"kw-ttt\">allopurinol</span> ; <span class=\"kw-ci\">ne pas alcaliniser les urines</span></p><ul><li><span class=\"kw-chiffre\">≥ 2/4</span> : <span class=\"kw-bio\">hyperuricémie</span> · <span class=\"kw-bio\">hyperkaliémie</span> · <span class=\"kw-bio\">hyperphosphorémie</span> · <span class=\"kw-bio\">hypocalcémie</span></li><li><span class=\"kw-bio\">LDH</span> élevées (reflet de la lyse) ; <span class=\"kw-alerte\">insuffisance rénale aiguë</span> quasi constante</li></ul><p><strong>Syndrome d'activation macrophagique <span class=\"q\">— rare, mortel sans traitement</span></strong></p><p>confirmation par <span class=\"kw-bio\">hémophagocytose</span> au myélogramme (non indispensable pour traiter) ; <span class=\"kw-ttt\">étoposide (VP16)</span> + <span class=\"kw-ttt\">corticoïdes</span> à forte dose</p><ul><li>Tableau bruyant : <span class=\"kw-clinique\">fièvre élevée</span> · <span class=\"kw-clinique\">hépato-splénomégalie</span> · <span class=\"kw-clinique\">syndrome confusionnel</span></li><li><span class=\"kw-bio\">cytopénies</span> · <span class=\"kw-bio\">hyperferritinémie</span> · <span class=\"kw-bio\">hypertriglycéridémie</span> · <span class=\"kw-bio\">hypofibrinogénémie</span> · <span class=\"kw-bio\">hyponatrémie</span></li></ul>","principes":"<p>Traitement guidé par le <strong>type histologique</strong> et le <strong><span class=\"kw-def\">stade</span></strong> (<span class=\"kw-def\">Ann Arbor</span>), discuté en <span class=\"kw-def\">RCP</span>. Base = <span class=\"kw-ttt\">polychimiothérapie</span>.</p><p><strong>Lymphome de Hodgkin</strong></p><p><span class=\"kw-ttt\">arrêt du tabac</span> (risque de second cancer)</p><ul><li>Polychimiothérapie <span class=\"kw-ttt\">ABVD</span> (<span class=\"kw-ttt\">anthracycline</span> · <span class=\"kw-ttt\">bléomycine</span> · <span class=\"kw-ttt\">vinblastine</span> · <span class=\"kw-ttt\">dacarbazine</span>)</li><li>Stades <span class=\"kw-chiffre\">localisés (I-II)</span> : <span class=\"kw-ttt\">ABVD</span> + <span class=\"kw-ttt\">radiothérapie</span> · stades <span class=\"kw-chiffre\">étendus (III-IV)</span> : <span class=\"kw-ttt\">ABVD</span> seul</li></ul><p><strong>LNH indolents (ex. folliculaire)</strong></p><ul><li>Faible <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span> : <span class=\"kw-ttt\">abstention-surveillance</span></li><li>Forte <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span> : <span class=\"kw-ttt\">R-CHOP</span></li></ul><p><strong>LNH agressifs (B diffus à grandes cellules, Burkitt)</strong></p><p>traitement <strong>toujours</strong> nécessaire d'emblée — <span class=\"kw-alerte\">urgence</span> thérapeutique pour le Burkitt</p><ul><li>Polychimiothérapie <span class=\"kw-ttt\">R-CHOP</span> (<span class=\"kw-ttt\">rituximab</span> · <span class=\"kw-ttt\">cyclophosphamide</span> · <span class=\"kw-ttt\">doxorubicine</span> · <span class=\"kw-ttt\">vincristine</span> · <span class=\"kw-ttt\">prednisone</span>)</li><li>Formes à risque / Burkitt : <span class=\"kw-ttt\">PL prophylactique</span> (<span class=\"kw-ttt\">méthotrexate</span> intrathécal) ± <span class=\"kw-ttt\">autogreffe de cellules souches</span></li></ul><p><strong>MALT / zone marginale liés à un agent <span class=\"kw-etio\">infectieux</span></strong></p><ul><li>MALT gastrique à <span class=\"kw-etio\">Helicobacter pylori</span> : <span class=\"kw-ttt\">éradication antibiotique</span> peut guérir le lymphome</li><li>Zone marginale splénique liée au <span class=\"kw-etio\">VHC</span> : <span class=\"kw-ttt\">traitement antiviral</span> ; <span class=\"kw-ttt\">splénectomie</span> si <span class=\"kw-clinique\">splénomégalie</span> symptomatique</li></ul><p><strong><span class=\"kw-ci\">Bilan pré-thérapeutique</span></strong></p><p>évaluation gériatrique spécialisée chez le sujet âgé</p><ul><li><span class=\"kw-bio\">ECG</span> + <span class=\"kw-imagerie\">ETT</span> avant <span class=\"kw-ttt\">anthracyclines</span> (ABVD et R-CHOP)</li><li><span class=\"kw-bio\">EFR avec DLCO</span> avant <span class=\"kw-ttt\">bléomycine</span> (ABVD) · <span class=\"kw-bio\">TSH</span> si <span class=\"kw-ttt\">radiothérapie cervicale</span></li><li><span class=\"kw-ttt\">Préservation de la fertilité</span> : cryoconservation de sperme (homme), vitrification ovocytaire (femme)</li></ul>","suivi":"<p>L'évaluation de la réponse au traitement repose sur la <span class=\"kw-imagerie\">TEP-TDM</span> (lymphomes avides de FDG) ; les <span class=\"kw-bio\">LDH</span> ont peu d'intérêt dans le <span class=\"kw-def\">suivi</span> post-thérapeutique.</p><p><strong>Lymphome de Hodgkin — complications tardives</strong></p><p><span class=\"kw-ttt\">arrêt du tabac</span> impératif (majore le risque de second cancer)</p><ul><li>Non malignes : <span class=\"kw-alerte\">IDM</span> · <span class=\"kw-bio\">hypothyroïdie</span> · <span class=\"kw-clinique\">stérilité</span></li><li>Secondes tumeurs : <span class=\"kw-alerte\">SMD / leucémie aiguë</span> · <span class=\"kw-alerte\">LNH</span> · <span class=\"kw-alerte\">cancer du sein</span> · <span class=\"kw-alerte\">cancer du poumon</span></li></ul><p><strong>LNH indolents — <span class=\"kw-clinique\">évolution</span></strong></p><ul><li><span class=\"kw-alerte\">Rechutes constantes</span>, de plus en plus rapprochées</li><li>Transformation en lymphome agressif (<span class=\"kw-chiffre\">~ 3 %/an</span>)</li></ul><p><strong>LNH agressifs — complications précoces</strong></p><ul><li><span class=\"kw-alerte\">Syndrome compressif</span> · <span class=\"kw-alerte\">syndrome de lyse</span> sous traitement</li><li><span class=\"kw-alerte\">Infections</span> (aplasie fébrile) · <span class=\"kw-alerte\">envahissement neuro-méningé</span></li></ul>"},"liensGlobaux":[{"href":"https://fr.wikipedia.org/wiki/Syndrome_de_S%C3%A9zary","label":"Wikipedia — Syndrome de sézary"},{"href":"https://www.sfdermato.org/media/pdf/fmc/syndrome-de-sezary-3e8b58298c40a9180ab1d9515737600d.pdf","label":"Syndrome de sezary 3e8b58298c40a9180ab1d9515737600d"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Lymphome confirmé (biopsie) — quelle stratégie ? — Tri initial : présence de cellules de Reed-Sternberg ?","detail":"<h4>CAT — stratégie thérapeutique du lymphome confirmé — Hodgkin <span class=\"kw-bio\">vs</span> non hodgkinien, puis <span class=\"kw-def\">stade</span> / comportement clinique</h4>","branches":[{"to":"q-lh","label":"Lymphome de Hodgkin (Reed-Sternberg +)","color":"blue"},{"to":"q-lnh","label":"Lymphome non hodgkinien","color":"blue"}]},{"id":"q-lh","kind":"decision","label":"Stade d'Ann Arbor ? — Localisé (I-II) vs étendu (III-IV)","branches":[{"to":"t-lh-loc","label":"Stades localisés (I-II)","color":"green"},{"to":"t-lh-ext","label":"Stades étendus (III-IV)","color":"amber"}]},{"id":"t-lh-loc","kind":"terminal","label":"Hodgkin localisé — ABVD + radiothérapie","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">ABVD</span> (<span class=\"kw-ttt\">anthracycline</span> · <span class=\"kw-ttt\">bléomycine</span> · <span class=\"kw-ttt\">vinblastine</span> · <span class=\"kw-ttt\">dacarbazine</span>) + <span class=\"kw-ttt\">radiothérapie</span></li></ul><h4>Mesures associées</h4><ul><li><span class=\"kw-ttt\">Arrêt du tabac</span> (risque de second cancer)</li><li><span class=\"kw-imagerie\">ETT</span> avant <span class=\"kw-ttt\">anthracycline</span> · <span class=\"kw-bio\">EFR + DLCO</span> avant <span class=\"kw-ttt\">bléomycine</span> · <span class=\"kw-bio\">TSH</span> si <span class=\"kw-ttt\">radiothérapie cervicale</span></li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li>Guérison <span class=\"kw-chiffre\">~ 90 %</span> tous stades confondus</li></ul>"},{"id":"t-lh-ext","kind":"terminal","label":"Hodgkin étendu — ABVD seul","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">ABVD</span> seul (sans <span class=\"kw-ttt\">radiothérapie</span> systématique)</li></ul><h4><span class=\"kw-ci\">Bilan pré-thérapeutique</span></h4><ul><li><span class=\"kw-imagerie\">ETT</span> (<span class=\"kw-ttt\">anthracycline</span>) · <span class=\"kw-bio\">EFR + DLCO</span> (<span class=\"kw-ttt\">bléomycine</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Réponse évaluée par <span class=\"kw-imagerie\">TEP-TDM</span> ; complications surtout <span class=\"kw-alerte\">tardives</span> (<span class=\"kw-alerte\">IDM</span>, hypothyroïdie, stérilité, seconds cancers)</li></ul>"},{"id":"q-lnh","kind":"decision","label":"Comportement clinique ? — Indolent (bas grade) vs agressif (haut grade)","branches":[{"to":"q-indolent","label":"Indolent / bas grade (ex. folliculaire)","color":"blue"},{"to":"q-agressif","label":"Agressif / haut grade (LBDGC, Burkitt)","color":"amber"}]},{"id":"q-indolent","kind":"decision","label":"Masse tumorale ? — Faible vs forte masse","branches":[{"to":"t-abstention","label":"Faible masse / paucisymptomatique","color":"blue"},{"to":"t-indolent-rchop","label":"Forte masse tumorale","color":"amber"}]},{"id":"t-abstention","kind":"terminal","label":"Abstention-surveillance","color":"blue","detail":"<h4>Indication</h4><ul><li>LNH <span class=\"kw-def\">indolent</span> de <span class=\"kw-chiffre\">faible masse tumorale</span>, paucisymptomatique</li></ul><h4>Conduite</h4><ul><li>Pas de traitement d'emblée ; <span class=\"kw-ttt\">surveillance</span> rapprochée</li></ul><h4>Cas particulier</h4><ul><li>MALT gastrique à <span class=\"kw-etio\">H. pylori</span> → <span class=\"kw-ttt\">éradication antibiotique</span> · zone marginale splénique à <span class=\"kw-etio\">VHC</span> → <span class=\"kw-ttt\">traitement antiviral</span> ± <span class=\"kw-ttt\">splénectomie</span></li></ul><h4><span class=\"kw-clinique\">Évolution</span></h4><ul><li><span class=\"kw-alerte\">Rechutes</span> constantes ; transformation en lymphome agressif (<span class=\"kw-chiffre\">~ 3 %/an</span>)</li></ul>"},{"id":"t-indolent-rchop","kind":"terminal","label":"LNH indolent forte masse — R-CHOP","color":"amber","detail":"<h4>Indication</h4><ul><li>LNH <span class=\"kw-def\">indolent</span> de <span class=\"kw-chiffre\">forte masse tumorale</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">R-CHOP</span> (<span class=\"kw-ttt\">rituximab</span> + <span class=\"kw-ttt\">CHOP</span>)</li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li>Guérison <span class=\"kw-alerte\">exceptionnelle</span> mais survie médiane prolongée (~ <span class=\"kw-chiffre\">10-15 ans</span>)</li></ul>"},{"id":"q-agressif","kind":"decision","label":"Forme Burkitt / urgence métabolique ? — Forte masse à croissance rapide, risque de lyse","branches":[{"to":"t-burkitt","label":"Oui — Burkitt / syndrome de lyse","color":"red"},{"to":"t-lbdgc","label":"Non — LBDGC standard","color":"amber"}]},{"id":"t-burkitt","kind":"terminal","label":"Urgence thérapeutique — Burkitt","color":"red","detail":"<h4><span class=\"kw-alerte\">Urgence</span></h4><ul><li><span class=\"kw-alerte\">Urgence thérapeutique</span> : <span class=\"kw-alerte\">syndrome de lyse tumorale</span> (spontané ou sous <span class=\"kw-ttt\">chimiothérapie</span>)</li></ul><h4>Prévention de la lyse</h4><ul><li><span class=\"kw-ttt\">hyperhydratation</span> + <span class=\"kw-ttt\">rasburicase</span> (hyperleucocytose / forte <span class=\"kw-clinique\">masse</span>) ou <span class=\"kw-ttt\">allopurinol</span> ; <span class=\"kw-ci\">ne pas alcaliniser les urines</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chimiothérapie intensive</span> (plus intensive que les autres lymphomes) + <span class=\"kw-ttt\">PL prophylactique</span> (<span class=\"kw-ttt\">méthotrexate</span> intrathécal)</li></ul><h4>Diagnostic</h4><ul><li><span class=\"kw-bio\">Biopsie</span> la moins invasive ; pas d'<span class=\"kw-ttt\">exérèse</span> complète (retarde la <span class=\"kw-ttt\">chimiothérapie</span>)</li></ul>"},{"id":"t-lbdgc","kind":"terminal","label":"LBDGC — R-CHOP","color":"amber","detail":"<h4>Traitement</h4><ul><li>Polychimiothérapie <span class=\"kw-ttt\">R-CHOP</span> : <span class=\"kw-ttt\">rituximab</span> · <span class=\"kw-ttt\">cyclophosphamide</span> · <span class=\"kw-ttt\">doxorubicine</span> · <span class=\"kw-ttt\">vincristine</span> · <span class=\"kw-ttt\">prednisone</span></li></ul><h4>Mesures associées</h4><ul><li><span class=\"kw-ttt\">PL prophylactique</span> (<span class=\"kw-ttt\">méthotrexate</span> intrathécal) ± <span class=\"kw-ttt\">autogreffe de cellules souches</span> selon le risque</li></ul><h4><span class=\"kw-ci\">Bilan pré-thérapeutique</span></h4><ul><li><span class=\"kw-imagerie\">ETT</span> + <span class=\"kw-bio\">ECG</span> avant <span class=\"kw-ttt\">anthracycline</span> ; <span class=\"kw-bio\">sérologies</span> <span class=\"kw-bio\">VHB</span> / <span class=\"kw-bio\">VHC</span> / <span class=\"kw-bio\">VIH</span></li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li><span class=\"kw-def\">Pronostic</span> par <span class=\"kw-def\">IPI</span> ; guérison possible (~ <span class=\"kw-chiffre\">50 %</span>)</li></ul>"}]},"cards":[{"i":"389bfd74b212","n":319,"o":"319-1","u":"Diagnostic positif","t":"Connaître les signes cliniques qui peuvent faire suspecter un lymphome","q":"Quels sont les signes généraux évocateurs d'un lymphome, aussi appelés symptômes B ?","a":"<p>Les symptômes B, très évocateurs, incluent :</p><ul><li>Une <strong>fièvre</strong> ou fébricule au long cours : ≥ 38 °C pendant ≥ 8 jours, sans cause infectieuse identifiée.</li><li>Des <strong>sueurs</strong> profuses, notamment nocturnes.</li><li>Un <strong>amaigrissement</strong> significatif : > 10 % du poids en < 6 mois.</li><li>Une <strong>altération de l'état général</strong> (AEG).</li></ul>"},{"i":"3f611c655d7e","n":319,"o":"319-1","u":"Diagnostic positif","t":"Connaître les signes cliniques qui peuvent faire suspecter un lymphome","q":"Quelle manifestation cutanée doit faire évoquer un lymphome de Hodgkin même en l'absence d'adénopathie superficielle ?","a":"<p>Un <strong>prurit chronique</strong>, apparemment isolé et sans autre cause évidente, doit faire évoquer un <strong>lymphome de Hodgkin</strong>.</p>"},{"i":"4218f8031589","n":319,"o":"319-1","u":"Diagnostic positif","t":"Connaître les signes cliniques qui peuvent faire suspecter un lymphome","q":"Quels types de manifestations cliniques peuvent faire suspecter un lymphome ?","a":"<p>Un lymphome se révèle par une association de manifestations :</p><ul><li>Un <strong>syndrome tumoral</strong> (atteinte des organes lymphoïdes).</li><li>Des <strong>signes généraux</strong> (dits symptômes B).</li></ul>"},{"i":"a9c98bfc04a0","n":319,"o":"319-1","u":"Diagnostic positif","t":"Connaître les signes cliniques qui peuvent faire suspecter un lymphome","q":"Quelles sont les atteintes extra-ganglionnaires possibles au cours d'un lymphome ?","a":"<p>Les atteintes extra-ganglionnaires sont variées et peuvent concerner :</p><ul><li><strong>Tube digestif</strong> : troubles dyspeptiques, diarrhée, hémorragie digestive.</li><li><strong>ORL</strong> : sinus, glandes salivaires, thyroïde.</li><li><strong>Cutané</strong> : nodules, plaques, érythrodermie.</li><li><strong>Œil</strong> : lésions conjonctivales, exophtalmie.</li><li><strong>SNC</strong> : confusion, crise comitiale, déficit moteur.</li><li><strong>Testicule</strong> : masse scrotale (chez le sujet âgé).</li></ul>"},{"i":"adabf2710c03","n":319,"o":"319-1","u":"Diagnostic positif","t":"Connaître les signes cliniques qui peuvent faire suspecter un lymphome","q":"Quelles sont les caractéristiques d'une adénopathie superficielle suspecte de lymphome ?","a":"<p>Une adénopathie superficielle est suspecte si elle présente les caractéristiques suivantes :</p><ul><li><strong>Taille</strong> : > 2 cm.</li><li><strong>Ancienneté</strong> : > 1 mois.</li><li><strong>Consistance</strong> : <strong>ferme</strong>, non inflammatoire.</li><li><strong>Mobilité</strong> : mobile, non adhérente aux plans superficiels et profonds.</li><li><strong>Douleur</strong> : <strong>indolore</strong> (sauf le cas rare mais très évocateur d'un lymphome de Hodgkin où la douleur est déclenchée par l'ingestion d'alcool).</li><li>Signes négatifs : <strong>pas de porte d'entrée infectieuse</strong> ni de lésion tumorale locorégionale.</li></ul>"},{"i":"be07f1782393","n":319,"o":"319-1","u":"Diagnostic positif","t":"Connaître les signes cliniques qui peuvent faire suspecter un lymphome","q":"Quelles sont les manifestations cliniques d'un lymphome avec des adénopathies profondes ou une atteinte viscérale abdominale ou médiastinale ?","a":"<ul><li><strong>Médiastin</strong> : dyspnée, toux, <strong>syndrome cave supérieur</strong>.</li><li><strong>Abdomen</strong> : syndrome occlusif (ex: lymphome de Burkitt iléo-cæcal), <strong>ascite</strong>, <strong>hépato-splénomégalie</strong>.</li></ul>"},{"i":"c8a903f61600","n":319,"o":"319-1","u":"Diagnostic positif","t":"Connaître les signes cliniques qui peuvent faire suspecter un lymphome","q":"Quels sont les signes cliniques associés à une atteinte de l'anneau de Waldeyer dans le cadre d'un lymphome ?","a":"<p>Une hypertrophie de l'anneau de Waldeyer (amygdales, base de langue, cavum) peut être :</p><ul><li><strong>Asymptomatique</strong>.</li><li>Ou se manifester par une <strong>dysphagie</strong>, une <strong>odynophagie</strong>, une <strong>dysphonie</strong>, ou une <strong>otalgie réflexe</strong>.</li></ul>"},{"i":"45a4c252a73e","n":319,"o":"319-2","u":"Identifier une urgence","t":"Connaître les situations d’urgence dans les lymphomes","q":"Comment prévenir le syndrome de lyse tumorale chez un patient atteint de lymphome ?","a":"<p>La prévention du syndrome de lyse tumorale repose sur :</p><ul><li>Une <strong>hyperhydratation</strong> par solution de <strong>sérum physiologique</strong> afin de maintenir une diurèse satisfaisante.</li><li>L'administration d'un <strong>hypouricémiant</strong> adapté au risque :<ul><li>La <strong>rasburicase</strong> si hyperleucocytose ou forte masse tumorale.</li><li>L'<strong>allopurinol</strong> dans les autres cas.</li></ul></li></ul>"},{"i":"752208f889b6","n":319,"o":"319-2","u":"Identifier une urgence","t":"Connaître les situations d’urgence dans les lymphomes","q":"Comment reconnaître cliniquement un syndrome de la veine cave supérieure et quel est le moyen mnémotechnique associé ?","a":"<p>Le syndrome de la veine cave supérieure se reconnaît cliniquement par les signes suivants (moyen mnémotechnique <strong>TOCTOC</strong>) :</p><ul><li><strong>T</strong>urgescence jugulaire</li><li>Œdème en <strong>p</strong>èlerine (visage, cou, thorax supérieur)</li><li><strong>C</strong>irculation veineuse collatérale thoracique</li><li><strong>O</strong>rthopnée / <strong>T</strong>oux</li><li><strong>C</strong>éphalées</li></ul>"},{"i":"8c215930f1ed","n":319,"o":"319-2","u":"Identifier une urgence","t":"Connaître les situations d’urgence dans les lymphomes","q":"Quels sont les signes cliniques et biologiques d'un syndrome d'activation macrophagique (SAM) chez un patient lymphomateux ?","a":"<p>Le syndrome d'activation macrophagique (SAM) est rare mais potentiellement mortel sans traitement. La clinique est bruyante :</p><ul><li><strong>Fièvre élevée</strong></li><li><strong>Hépato-splénomégalie</strong></li><li><strong>Syndrome confusionnel</strong></li></ul><p>La biologie est caractérisée par :</p><ul><li><strong>Cytopénies</strong></li><li><strong>Hyperferritinémie</strong></li><li><strong>Hypertriglycéridémie</strong></li><li><strong>Hypofibrinogénémie</strong></li><li><strong>Hyponatrémie</strong></li></ul><p>La confirmation est faite par des images d'<strong>hémophagocytose au myélogramme</strong>, bien que ce ne soit pas indispensable pour initier le traitement.</p>"},{"i":"9d6b003d6b6b","n":319,"o":"319-2","u":"Identifier une urgence","t":"Connaître les situations d’urgence dans les lymphomes","q":"Quels sont les trois tableaux compressifs majeurs à rechercher en urgence chez un patient atteint de lymphome ?","a":"<p>Les trois tableaux compressifs majeurs sont :</p><ul><li>Le <strong>syndrome de la veine cave supérieure</strong> : compression de la veine cave par une masse médiastinale volumineuse.</li><li>La <strong>compression radiculo-médullaire</strong> : syndrome de compression médullaire ou syndrome de la queue de cheval.</li><li>La <strong>masse abdominale d'évolution rapide</strong> : entraînant douleurs et syndrome occlusif, pouvant révéler un lymphome de Burkitt et imposant la recherche d'un syndrome de lyse tumorale spontané.</li></ul>"},{"i":"b02d62ac76b6","n":319,"o":"319-2","u":"Identifier une urgence","t":"Connaître les situations d’urgence dans les lymphomes","q":"Quelle est la définition biologique du syndrome de lyse tumorale et quelles en sont les conséquences principales ?","a":"<p>La définition biologique du syndrome de lyse tumorale est la présence d'au moins <strong>2/4 anomalies</strong> parmi :</p><ul><li><strong>Hyperuricémie</strong></li><li><strong>Hyperkaliémie</strong></li><li><strong>Hyperphosphorémie</strong></li><li><strong>Hypocalcémie</strong></li></ul><p>Le marqueur principal est une <strong>élévation des LDH</strong> proportionnelle à la lyse.</p><p>Les conséquences principales sont :</p><ul><li>L'<strong>insuffisance rénale aiguë</strong> (quasi constante)</li><li>Des <strong>troubles du rythme cardiaque</strong></li><li>Des <strong>convulsions</strong></li></ul>"},{"i":"b2234129a66a","n":319,"o":"319-2","u":"Identifier une urgence","t":"Connaître les situations d’urgence dans les lymphomes","q":"Quels sont les deux grands types d'urgences rencontrées dans les lymphomes malins ?","a":"<p>Les urgences des lymphomes sont de deux ordres :</p><ul><li>Les urgences <strong>compressives</strong> : le syndrome tumoral comprime une structure vitale.</li><li>Les urgences <strong>métaboliques</strong> : liées à une lyse cellulaire massive ou une activation macrophagique.</li></ul><p>Elles concernent surtout les <strong>lymphomes agressifs</strong>.</p>"},{"i":"d1d3bb23e321","n":319,"o":"319-2","u":"Identifier une urgence","t":"Connaître les situations d’urgence dans les lymphomes","q":"Quel est le piège à éviter dans la prise en charge du syndrome de lyse tumorale et pourquoi ?","a":"<p>Le piège à éviter est de <strong>ne pas alcaliniser les urines</strong> au cours d'un syndrome de lyse tumorale.</p><p>L'alcalinisation augmente le risque de <strong>précipitation de cristaux de phosphate de calcium</strong> et aggrave ainsi le risque d'insuffisance rénale.</p>"}]};